using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using Microsoft.AspNetCore.Identity; using Microsoft.Extensions.Options; using Microsoft.IdentityModel.Tokens; using MongoDB.Driver; using SmartSolarMicrogrid.Api.Configuration; using SmartSolarMicrogrid.Api.Data; using SmartSolarMicrogrid.Api.DTOs; using SmartSolarMicrogrid.Api.Models;
namespace SmartSolarMicrogrid.Api.Services;
public interface IAuthService { Task<LoginResponse> LoginAsync(LoginRequest request); }
public sealed class AuthService(MongoContext db, IOptions<JwtOptions> jwt) : IAuthService { public async Task<LoginResponse> LoginAsync(LoginRequest r) { var user=await db.Users.Find(x=>x.Username==r.Username).FirstOrDefaultAsync()??throw new InvalidOperationException("Invalid username or password."); if(!user.IsActive||new PasswordHasher<User>().VerifyHashedPassword(user,user.PasswordHash,r.Password)!=PasswordVerificationResult.Success)throw new InvalidOperationException("Invalid username or password.");var o=jwt.Value;var exp=DateTime.UtcNow.AddMinutes(o.ExpiryMinutes);var claims=new[]{new Claim(ClaimTypes.NameIdentifier,user.Id),new Claim(ClaimTypes.Name,user.Username),new Claim(ClaimTypes.Role,user.Role),new Claim("nic",user.ProsumerNic??"")};var t=new JwtSecurityToken(o.Issuer,o.Audience,claims,expires:exp,signingCredentials:new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(o.Key)),SecurityAlgorithms.HmacSha256));return new(new JwtSecurityTokenHandler().WriteToken(t),exp,user.Username,user.Role,user.ProsumerNic); } }
public interface IUserService { Task<List<User>> GetAsync(); Task<User> CreateAsync(UserRequest r); Task<User> UpdateAsync(string id,UserUpdateRequest r); }
public sealed class UserService(MongoContext db) : IUserService { public Task<List<User>> GetAsync()=>db.Users.Find(_=>true).ToListAsync(); public async Task<User>CreateAsync(UserRequest r){if(!new[]{Roles.Backoffice,Roles.GridOperator,Roles.Prosumer}.Contains(r.Role))throw new InvalidOperationException("Invalid role.");if(await db.Users.Find(x=>x.Username==r.Username).AnyAsync())throw new InvalidOperationException("Username already exists.");if(r.Role==Roles.Prosumer&&string.IsNullOrWhiteSpace(r.ProsumerNic))throw new InvalidOperationException("Prosumer NIC is required.");var u=new User{Username=r.Username,Role=r.Role,ProsumerNic=r.ProsumerNic};u.PasswordHash=new PasswordHasher<User>().HashPassword(u,r.Password);await db.Users.InsertOneAsync(u);return u;}public async Task<User>UpdateAsync(string id,UserUpdateRequest r){var u=await db.Users.Find(x=>x.Id==id).FirstOrDefaultAsync()??throw new KeyNotFoundException("User not found.");if(!new[]{Roles.Backoffice,Roles.GridOperator,Roles.Prosumer}.Contains(r.Role))throw new InvalidOperationException("Invalid role.");u.Role=r.Role;u.IsActive=r.IsActive;u.UpdatedAt=DateTime.UtcNow;await db.Users.ReplaceOneAsync(x=>x.Id==id,u);return u;} }
public interface IProsumerService { Task<Prosumer> RegisterAsync(ProsumerRequest r); Task<Prosumer> GetAsync(string nic); Task<Prosumer> UpdateAsync(string nic,ProsumerUpdateRequest r); Task RequestDeactivationAsync(string nic); }
public sealed class ProsumerService(MongoContext db) : IProsumerService { public async Task<Prosumer>RegisterAsync(ProsumerRequest r){if(await db.Prosumers.Find(x=>x.Nic==r.Nic).AnyAsync())throw new InvalidOperationException("NIC already registered.");var p=new Prosumer{Nic=r.Nic,FullName=r.FullName,Email=r.Email,Phone=r.Phone,Address=r.Address};var u=new User{Username=r.Nic,Role=Roles.Prosumer,ProsumerNic=r.Nic};u.PasswordHash=new PasswordHasher<User>().HashPassword(u,r.Password);await db.Prosumers.InsertOneAsync(p);await db.Users.InsertOneAsync(u);return p;}public async Task<Prosumer>GetAsync(string nic)=>await db.Prosumers.Find(x=>x.Nic==nic).FirstOrDefaultAsync()??throw new KeyNotFoundException("Prosumer not found.");public async Task<Prosumer>UpdateAsync(string nic,ProsumerUpdateRequest r){var p=await GetAsync(nic);p.FullName=r.FullName;p.Email=r.Email;p.Phone=r.Phone;p.Address=r.Address;p.UpdatedAt=DateTime.UtcNow;await db.Prosumers.ReplaceOneAsync(x=>x.Nic==nic,p);return p;}public async Task RequestDeactivationAsync(string nic){var p=await GetAsync(nic);p.DeactivationRequested=true;p.UpdatedAt=DateTime.UtcNow;await db.Prosumers.ReplaceOneAsync(x=>x.Nic==nic,p);} }
